import test from 'node:test';
import assert from './assert.mjs';
import {JSDOM} from 'jsdom';
import {readFile} from 'node:fs/promises';
import {act,createElement as h,createRef,StrictMode} from 'react';
import {renderToString} from 'react-dom/server';
import {userEvent} from '@testing-library/user-event';
import {SignUpBlock,PasswordRecoveryBlock} from '@dmf-ui/react';
import {AuthenticationProof,renderAuthentication} from '../.test-dist/server.mjs';
test('packed authentication SSR preserves native values, extensions, localization and independent IDs',()=>{
 const html=renderToString(h('div',{},h(SignUpBlock,{id:'signup',action:'/create',confirmPassword:true,email:'initial@example.test',error:'Host error',fieldErrors:{confirmPassword:'Host confirmation'},fields:h('input',{name:'scope',defaultValue:'docs'}),footer:h('a',{href:'/help'},'Help')}),h(SignUpBlock,{id:'disabled',title:'Unavailable registration',action:'/create',disabled:true}),h(PasswordRecoveryBlock,{id:'recovery',action:'/recover',pending:true,fieldErrors:{email:'Review this address'},pendingLabel:'Memproses…'}),h(PasswordRecoveryBlock,{id:'complete',action:'/recover',complete:true})));
 const dom=new JSDOM(html);try{const d=dom.window.document,f=d.querySelector('#signup');assert.equal(f.method,'post');assert.equal(f.querySelectorAll('[autocomplete=new-password]').length,2);assert.equal(f.querySelector('[name=confirmPassword]').getAttribute('aria-describedby'),'signup-confirm-password-error');assert.equal(new dom.window.FormData(f).get('scope'),'docs');assert(f.querySelector('a[href="/help"]'));for(const input of d.querySelectorAll('[type=password]'))assert(!input.hasAttribute('value'));assert(d.querySelector('#disabled fieldset').disabled);assert.equal(d.querySelector('#disabled [name=confirmPassword]'),null);assert.equal(d.querySelector('#recovery-email').getAttribute('aria-describedby'),'recovery-email-error');assert(d.querySelector('#recovery fieldset').disabled);assert.equal(d.querySelector('#complete input'),null);assert(d.querySelector('#complete [role=status]').textContent.includes('If recovery is available'));const ids=[...d.querySelectorAll('[id]')].map(x=>x.id);assert.equal(ids.length,new Set(ids).size);}finally{dom.window.close();}
 assert.throws(()=>renderToString(h(SignUpBlock,{id:'bad',action:'/create',confirmPassword:true,confirmPasswordName:'email'})),/distinct/);
});
test('packed authentication hydrates native fields, pending/error/reset and recovery focus without reading credentials',async()=>{
 const dom=new JSDOM(`<div id="root">${renderAuthentication()}</div>`,{url:'https://consumer.test/authentication.html'}),saved=new Map(),warnings=[];
 for(const key of ['window','document','HTMLElement','HTMLInputElement','FormData','navigator','IS_REACT_ACT_ENVIRONMENT']){saved.set(key,Object.getOwnPropertyDescriptor(globalThis,key));Object.defineProperty(globalThis,key,{configurable:true,writable:true,value:key==='IS_REACT_ACT_ENVIRONMENT'?true:dom.window[key]});}
 let root;const old=console.error;console.error=(...args)=>warnings.push(args.join(' '));
 try{const {hydrateRoot}=await import('react-dom/client'),original=document.querySelector('#packed-signup-email');await act(async()=>{root=hydrateRoot(document.querySelector('#root'),h(StrictMode,{},h(AuthenticationProof)),{identifierPrefix:'authentication-',onRecoverableError:e=>warnings.push(String(e))});});assert(original===document.querySelector('#packed-signup-email'));
 const user=userEvent.setup({document}),signup=document.querySelector('#packed-signup'),recovery=document.querySelector('#packed-recovery');const press=async text=>act(async()=>user.click([...document.querySelectorAll('button')].find(b=>b.textContent===text)));
 await act(async()=>user.click(signup.querySelector('[type=submit]')));assert.equal(signup.checkValidity(),false);assert(!signup.querySelector('fieldset').disabled);
 await act(async()=>{await user.type(signup.elements.namedItem('email'),'reader@example.test');await user.type(signup.elements.namedItem('password'),'ephemeral-test');await user.type(signup.elements.namedItem('confirmPassword'),'ephemeral-test');await user.click(signup.querySelector('[type=submit]'));});assert(signup.querySelector('fieldset').disabled);assert.equal(new FormData(signup).has('password'),false);assert(!recovery.querySelector('fieldset').disabled);
 await press('Show host error');assert(signup.querySelector('[role=alert]'));assert.equal(signup.elements.namedItem('confirmPassword').getAttribute('aria-invalid'),'true');await press('Reset forms');assert.equal(signup.elements.namedItem('password').value,'');assert.equal(signup.elements.namedItem('email').value,'');
 await act(async()=>{await user.type(recovery.elements.namedItem('email'),'reader@example.test');await user.click(recovery.querySelector('[type=submit]'));});assert(recovery.querySelector('fieldset').disabled);await press('Finish demonstration');assert.equal(recovery.querySelector('input'),null);assert(document.activeElement===document.querySelector('#packed-recovery-completion'));assert(document.activeElement.textContent.includes('If recovery is available'));await press('Reset forms');assert.equal(recovery.elements.namedItem('email').value,'');assert.deepEqual(warnings,[]);
 }finally{if(root)await act(async()=>root.unmount());console.error=old;dom.window.close();for(const [key,value]of saved){if(value)Object.defineProperty(globalThis,key,value);else delete globalThis[key];}}
});
test('packed new Block native refs, reset defaults and unmount cleanup remain host owned',async()=>{
 const dom=new JSDOM('<div id="root"></div>'),saved=new Map();for(const key of ['window','document','HTMLElement','IS_REACT_ACT_ENVIRONMENT']){saved.set(key,Object.getOwnPropertyDescriptor(globalThis,key));Object.defineProperty(globalThis,key,{configurable:true,writable:true,value:key==='IS_REACT_ACT_ENVIRONMENT'?true:dom.window[key]});}let root;
 try{const {createRoot}=await import('react-dom/client'),ref=createRef();root=createRoot(document.querySelector('#root'));for(const Block of [SignUpBlock,PasswordRecoveryBlock]){await act(async()=>root.render(h(Block,{id:'bare',action:'/account',email:'authored@example.test',ref})));assert.equal(ref.current.tagName,'FORM');ref.current.elements.namedItem('email').value='changed@example.test';ref.current.reset();assert.equal(ref.current.elements.namedItem('email').value,'authored@example.test');}await act(async()=>root.unmount());root=null;assert.equal(ref.current,null);}finally{if(root)await act(async()=>root.unmount());dom.window.close();for(const [key,value]of saved){if(value)Object.defineProperty(globalThis,key,value);else delete globalThis[key];}}
});
test('production authentication specimen guards unenhanced submissions and contains no password values',async()=>{const html=await readFile('dist/authentication.html','utf8'),dom=new JSDOM(html);try{for(const form of dom.window.document.querySelectorAll('form'))assert(form.querySelector('[type=submit]').disabled);assert(!/<input[^>]*type="password"[^>]*value=/.test(html));}finally{dom.window.close();}});
